# В dip можно ссылаться и на новые страны (SI, HU, FI): если страны нет в сборке, движок такой ключ пропускает.
from sk_lib import g


def O(l, **fx):
    return {"l": l, "fx": fx}


def E(t, *opts, **kw):
    d = {"t": t, "o": list(opts)}
    d.update(kw)
    return d


